  "Reciprocity": {"Explanation": "The email offers something (self-defense techniques) and asks for a favor (clicking on the link or sending a check), which creates a sense of obligation in the recipient."},
  "Scarcity": {"Explanation": "The email creates urgency by implying limited time (2-3 weeks for delivery) and a limited opportunity (the recipient may not have the chance to defend themselves before they become a victim)."},
  "Authority": {"Explanation": "The email claims credibility through the author's experience as a martial arts instructor and their association with recognized institutions (Kenpo Karate, Tae Kwan Do, Kung Fu, Hapkido, and ISFA Shootfighting)."},
  "Commitment/Consistency": {"Explanation": "Not present, as the email does not reference prior behavior or choices of the recipient."},
  "Liking": {"Explanation": "Not present, as the email does not use familiarity, flattery, or personalization to build trust or rapport with the recipient."},
  "Social proof": {"Explanation": "Not present, as the email does not reference other people's participation or endorsement."}
}

